def harvest_block_default_actions(
    block_ids: Sequence[str],
    *roots: Any,
    workspace: Any = None,
) -> Dict[str, str]:
    """capability BLOCK_IDS → keyword actions for keep-path emit."""
    out: Dict[str, str] = {}
    for raw in block_ids or ():
        bid = str(raw or "").strip()
