def _shape_workflow_steps(
    steps,
    roster,
    *,
    product_name,
    entity,
    default_actions,
    fallback_domain,
):
    shaped = []
    for step in steps:
        if not isinstance(step, dict):
            shaped.append(step)
            continue
        item = dict(step)
        bid = _workflow_step_block(item)
        if not bid:
            shaped.append(item)
            continue
        raw = item.get("input")
