    return len(body) >= 8 and all(c in "0123456789abcdefABCDEF" for c in body)


def _team_registry_knows(team_id):
    """True when the team block's own registry has this team id.

    The block resolves STORAGE_PATH at call time (default ./storage, same
    convention as the rest of the Store), so a cached precondition id must
    be checked against the registry that will actually be read. Without
    this, a phase that moves STORAGE_PATH hands the block an id from the
    previous root and the capability fails 'Team access denied'.
    """
    from pathlib import Path

    root = Path(os.getenv("STORAGE_PATH", "./storage")) / "team"
    try:
        raw = json.loads((root / "state.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    teams = raw.get("teams") if isinstance(raw, dict) else None
    return isinstance(teams, dict) and str(team_id) in teams


